import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/getting-started/installation.md","filePath":"openshield-xdp/getting-started/installation.md","lastUpdated":null}'),s={name:"openshield-xdp/getting-started/installation.md"};function n(o,e,r,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Linux kernel ≥ 5.15 (recommended ≥ 6.10 for full feature set)</li><li><code>CONFIG_DEBUG_INFO_BTF=y</code> in kernel config</li><li>XDP-capable NIC driver (native mode) or any NIC (generic/skb mode)</li><li><code>clang</code> ≥ 12, <code>llvm</code>, <code>bpftool</code>, <code>libbpf-dev</code></li><li><code>Go</code> ≥ 1.21</li></ul><div class="tip custom-block"><p class="custom-block-title">Check BTF</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/kernel/btf/vmlinux</span></span></code></pre></div><p>If this file doesn&#39;t exist, your kernel was compiled without BTF support. Rebuild with <code>CONFIG_DEBUG_INFO_BTF=y</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Kernel feature gates</p><p>OpenShield-XDP automatically detects available kernel features at load time and silently disables features your kernel doesn&#39;t support. For example:</p><ul><li><strong>Bloom filter maps</strong> require kernel 5.16+ — if unavailable, the LRU hashmap whitelist is used instead</li><li><strong>freplace</strong> requires kernel 5.15+ — if unavailable, all BPF logic runs in the main program (no hot-patching)</li><li><strong>BPF timers</strong> require kernel 5.15+ — connection tracking uses a simpler mechanism without them</li></ul><p>Run <code>openshield status</code> after loading to see which features are active on your kernel.</p></div><h2 id="one-liner-install" tabindex="-1">One-liner install <a class="header-anchor" href="#one-liner-install" aria-label="Permalink to &quot;One-liner install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div>',7)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
